INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'souq-naqel-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Souq Al-Bahrain in Tubli.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من سوق البحرين في Tubli.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics. Focusing on Smart Home Setup & Wi-Fi Mesh, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع. من خلال خدمة تركيب المنزل الذكي وشبكات الواي فاي نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Omnichannel Bahraini e-commerce retailer operating same-day local delivery, click-and-collect counters, and smart home electronics.</p><p>Focusing on <strong>Smart Home Setup & Wi-Fi Mesh</strong>, our Tubli specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>متجر إلكتروني بحريني متعدد القنوات يوفر التوصيل في نفس اليوم والاستلام من الفروع.</p><p>من خلال خدمة <strong>تركيب المنزل الذكي وشبكات الواي فاي</strong>، يعمل فريقنا في Tubli على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Souq Al-Bahrain', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | سوق البحرين', 'Executive guide by Souq Al-Bahrain covering Smart Home Setup & Wi-Fi Mesh benchmarks in Bahrain.', 'دليل تنفيذي من سوق البحرين حول معايير تركيب المنزل الذكي وشبكات الواي فاي في البحرين.', 'Sustainability', '{"online_store","sustainability","Tubli","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
