press Delivery benchmarks in Bahrain.', 'دليل تنفيذي من سوق البحرين حول معايير توصيل فوري خلال ساعتين في المنامة في البحرين.', 'Client Care', '{"online_store","client care","Tubli","2026"}'::text[], 'Bader Ali', 'published', now() - interval '72 days', false, now() - interval '72 days', now()) ON CONFLICT (id) DO NOTHING;
